#!/usr/bin/env node
// Colour classes -> semantic roles. A generic engine: which colours exist, which
// role each becomes and which need a human are declarative rules (rules.json);
// the role vocabulary is generated by the brand build (scripts/brand/generated/roles.json).
// No colour or role name is written here.
//
//   npm run theme:migrate -- --report [glob...]             JSON: mapped / ambiguous / unmapped per file and line
//   npm run theme:migrate -- --report --patterns [glob...]  recurring colour-class combinations (component variants)
//   npm run theme:migrate -- --write  [glob...]             rewrite the files (idempotent)
//   npm run theme:migrate -- --check  [glob...]             exit 1 while a non-semantic colour class remains
//
// Globs are relative to the repository root; default: the frontend sources.

import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { ROOT } from '../brand/lib/tokens.mjs';

export const RULES_FILE = path.join(ROOT, 'scripts', 'theme', 'rules.json');
export const VOCABULARY_FILE = path.join(ROOT, 'scripts', 'brand', 'generated', 'roles.json');
const DEFAULT_GLOBS = ['web_client/{app,components,lib,hooks}/**/*.{ts,tsx,css}'];
const FAMILY = '<family>';

const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const inRange = (v, range) => !range || (v >= range[0] && v <= range[1]);
const asList = (v) => (v === undefined || v === '*' ? undefined : [v].flat());

/** Role vocabulary generated by the brand build. */
export function loadVocabulary(file = VOCABULARY_FILE) {
    const { roles, textRoles } = JSON.parse(fs.readFileSync(file, 'utf8'));
    return { roles, textRoles };
}

/**
 * Validate and index a rules spec against the role vocabulary.
 * Every target role must exist; no rule may leave an opacity modifier on a text role.
 */
export function compileRules(spec, vocab) {
    const groupOf = new Map();
    for (const [group, colors] of Object.entries(spec.colors ?? {})) for (const c of colors) groupOf.set(c, group);
    const familyOf = new Map();
    for (const [family, colors] of Object.entries(spec.families ?? {})) for (const c of colors) familyOf.set(c, family);
    const known = new Set([...groupOf.keys(), ...familyOf.keys()]);
    const utilities = [...spec.utilities].sort((a, b) => b.length - a.length);

    const rules = spec.rules.map((rule, i) => {
        const where = `rule ${i} (${JSON.stringify(rule.match)})`;
        const m = rule.match ?? {};
        for (const c of asList(m.color) ?? []) if (!known.has(c)) throw new Error(`${where}: unknown colour "${c}"`);
        for (const g of asList(m.group) ?? []) if (!spec.colors?.[g]) throw new Error(`${where}: unknown colour group "${g}"`);
        for (const f of asList(m.family) ?? []) if (!spec.families?.[f]) throw new Error(`${where}: unknown family "${f}"`);
        for (const u of asList(m.utility) ?? []) if (!spec.utilities.includes(u)) throw new Error(`${where}: unknown utility "${u}"`);

        const t = rule.to ?? {};
        const targets = [...(t.role ? [['*', t.role]] : []), ...Object.entries(t.byUtility ?? {})];
        const families = asList(m.family);
        for (const [utility, role] of targets) {
            if (role.includes(FAMILY) && !families) throw new Error(`${where}: target "${role}" uses ${FAMILY} but the rule matches no family`);
            const resolved = role.includes(FAMILY) ? families.map((f) => role.replaceAll(FAMILY, f)) : [role];
            for (const r of resolved) {
                if (!vocab.roles.includes(r)) throw new Error(`${where}: target role "${r}" is not in roles.json`);
                const textUtility = utility === 'text' || (utility === '*' && (asList(m.utility) ?? ['text']).includes('text'));
                if (t.keepOpacity && textUtility && vocab.textRoles.includes(r)) {
                    throw new Error(`${where}: would keep an opacity modifier on text role "${r}"`);
                }
            }
        }
        if (!targets.length && !t.drop && !t.ambiguous) throw new Error(`${where}: "to" needs role, byUtility, drop or ambiguous`);
        return { ...rule, match: m, to: t };
    });

    const colorAlt = [...known].sort((a, b) => b.length - a.length).map(escape).join('|');
    const utilAlt = utilities.map(escape).join('|');
    // A whole class token: variants (hover:, md:, data-[state=open]:), optional !, utility-colour[-shade][/opacity].
    const g = (capture) => (capture ? '(' : '(?:');
    const classPattern = (c) =>
        `(?<![\\w/-])${g(c)}(?:[\\w-]+(?:\\[[^\\]\\s]*\\])?:)*)${g(c)}!?)${g(c)}${utilAlt})-${g(c)}${colorAlt})(?:-${g(c)}\\d{2,3}))?(?:/${g(c)}\\d{1,3}|\\[\\d*\\.?\\d+%?\\]))?(?![\\w/-])`;
    const token = new RegExp(classPattern(true), 'g');
    const exact = new RegExp(`^${classPattern(true)}$`);
    // The bare class with the spaces around it: a dropped class takes one of them along.
    const spaced = new RegExp(`( ?)(${classPattern(false)})( ?)`, 'g');
    // A text-like utility on a role that is not a text role (text-primary, placeholder-accent): its
    // contrast is never checked as text. Only reported, never rewritten.
    const nonText = vocab.roles.filter((r) => !vocab.textRoles.includes(r)).sort((a, b) => b.length - a.length);
    const misuse = spec.textUtilities?.length
        ? new RegExp(
              `(?<![\\w/-])(?:[\\w-]+(?:\\[[^\\]\\s]*\\])?:)*!?(?:${spec.textUtilities.map(escape).join('|')})-(${nonText.map(escape).join('|')})(?:/\\d{1,3})?(?![\\w/-])`,
              'g',
          )
        : null;
    return { rules, groupOf, familyOf, token, exact, spaced, misuse, utilities };
}

export function loadRules(file = RULES_FILE, vocab = loadVocabulary()) {
    return compileRules(JSON.parse(fs.readFileSync(file, 'utf8')), vocab);
}

function parse(cls, compiled) {
    const m = compiled.exact.exec(cls);
    if (!m) return null;
    return { variants: m[1], important: m[2], utility: m[3], color: m[4], shade: m[5] ? Number(m[5]) : undefined, opacity: m[6] ? opacityPercent(m[6]) : undefined };
}

/** 40, [40], [40%] and [0.4] are the same opacity: always returned as a percentage. */
function opacityPercent(raw) {
    if (!raw.startsWith('[')) return Number(raw);
    const v = raw.slice(1, -1);
    if (v.endsWith('%')) return Number(v.slice(0, -1));
    const n = Number(v);
    return n <= 1 ? Math.round(n * 100) : n;
}

function matches(match, p, compiled) {
    const family = compiled.familyOf.get(p.color);
    return (
        (asList(match.utility)?.includes(p.utility) ?? true) &&
        (asList(match.color)?.includes(p.color) ?? true) &&
        (asList(match.group)?.includes(compiled.groupOf.get(p.color)) ?? true) &&
        (match.family === undefined || (family !== undefined && asList(match.family).includes(family))) &&
        (match.shade === undefined || (p.shade !== undefined && inRange(p.shade, match.shade))) &&
        inRange(p.opacity ?? 100, match.opacity)
    );
}

/**
 * @returns {{ status: 'none'|'mapped'|'dropped'|'ambiguous'|'unmapped', to?: string, reason?: string, parsed?: object }}
 *   'none': not a non-semantic colour class (left alone).
 */
export function migrateClass(cls, compiled) {
    const p = parse(cls, compiled);
    if (!p) return { status: 'none' };
    const rule = compiled.rules.find((r) => matches(r.match, p, compiled));
    if (!rule) return { status: 'unmapped', parsed: p };
    const t = rule.to;
    if (t.ambiguous) return { status: 'ambiguous', reason: t.ambiguous, parsed: p };
    if (t.drop) return { status: 'dropped', to: '', parsed: p };
    const role = (t.byUtility?.[p.utility] ?? t.byUtility?.['*'] ?? t.role)?.replaceAll(FAMILY, compiled.familyOf.get(p.color));
    if (!role) return { status: 'unmapped', reason: `no role for utility "${p.utility}"`, parsed: p };
    const opacity = t.keepOpacity && p.opacity !== undefined ? `/${p.opacity}` : '';
    return { status: 'mapped', to: `${p.variants}${p.important}${p.utility}-${role}${opacity}`, parsed: p };
}

/** Rewrite every colour class of a source text; findings carry the 1-based line. */
export function migrateSource(text, compiled) {
    const findings = [];
    const lineStarts = [0];
    for (let i = text.indexOf('\n'); i !== -1; i = text.indexOf('\n', i + 1)) lineStarts.push(i + 1);
    const lineOf = (offset) => {
        let lo = 0;
        let hi = lineStarts.length - 1;
        while (lo < hi) {
            const mid = (lo + hi + 1) >> 1;
            if (lineStarts[mid] <= offset) lo = mid;
            else hi = mid - 1;
        }
        return lo + 1;
    };
    const out = text.replace(compiled.spaced, (all, lead, cls, trail, offset) => {
        const r = migrateClass(cls, compiled);
        findings.push({ line: lineOf(offset + lead.length), from: cls, to: r.to, status: r.status, ...(r.reason && { reason: r.reason }) });
        if (r.status === 'dropped') return lead && trail ? ' ' : '';
        return `${lead}${r.status === 'mapped' ? r.to : cls}${trail}`;
    });
    for (const m of compiled.misuse ? out.matchAll(compiled.misuse) : []) {
        findings.push({
            line: lineOf(m.index),
            from: m[0],
            status: 'misuse',
            reason: `"${m[1]}" is not a text role: use a text role (${m[1]}-ink, on-${m[1]}, ink, ...)`,
        });
    }
    return { text: out, findings };
}

/** Colour-class combinations recurring in the same string literal at least `min` times. */
export function colorPatterns(sources, compiled, min = 3) {
    const groups = new Map();
    for (const [file, text] of sources) {
        for (const [literal] of text.matchAll(/"[^"\n]*"|'[^'\n]*'|`[^`]*`/g)) {
            const classes = [...literal.matchAll(compiled.token)].map((m) => m[0]).filter((c) => migrateClass(c, compiled).status !== 'none');
            if (classes.length < 2) continue;
            const key = [...new Set(classes)].sort().join(' ');
            const g = groups.get(key) ?? { classes: key.split(' '), count: 0, files: new Set() };
            g.count++;
            g.files.add(file);
            groups.set(key, g);
        }
    }
    return [...groups.values()]
        .filter((g) => g.count >= min)
        .sort((a, b) => b.count - a.count)
        .map((g) => ({ ...g, files: [...g.files].sort() }));
}

const EXCLUDE = [/[\\/]__tests__[\\/]/, /\.generated\.ts$/, /[\\/]brand-tokens\.css$/];

export function sourceFiles(globs = DEFAULT_GLOBS) {
    const files = new Set(globs.flatMap((g) => fs.globSync(g, { cwd: ROOT })));
    // A broad glob (dir/**) also matches directories: keep regular files only.
    return [...files].filter((f) => !EXCLUDE.some((re) => re.test(f)) && fs.statSync(path.join(ROOT, f)).isFile()).sort();
}

function main(argv) {
    const mode = ['--report', '--write', '--check'].find((m) => argv.includes(m));
    if (!mode) {
        console.error('usage: migrate.mjs --report [--patterns] | --write | --check [glob...]');
        process.exit(2);
    }
    const globs = argv.filter((a) => !a.startsWith('--'));
    const compiled = loadRules();
    const files = sourceFiles(globs.length ? globs : undefined);
    const sources = files.map((f) => [f.replaceAll('\\', '/'), fs.readFileSync(path.join(ROOT, f), 'utf8')]);

    if (argv.includes('--patterns')) {
        console.log(JSON.stringify(colorPatterns(sources, compiled), null, 2));
        return;
    }
    const report = { files: files.length, mapped: 0, dropped: 0, ambiguous: [], unmapped: [], misuse: [] };
    let changed = 0;
    for (const [file, text] of sources) {
        const { text: out, findings } = migrateSource(text, compiled);
        for (const f of findings) {
            if (f.status === 'mapped') report.mapped++;
            else if (f.status === 'dropped') report.dropped++;
            else report[f.status].push({ file, line: f.line, class: f.from, ...(f.reason && { reason: f.reason }) });
        }
        if (mode === '--write' && out !== text) {
            fs.writeFileSync(path.join(ROOT, file), out);
            changed++;
        }
    }
    if (mode === '--report') {
        console.log(JSON.stringify(report, null, 2));
    } else if (mode === '--write') {
        console.log(`rewrote ${changed} file(s); ${report.ambiguous.length} ambiguous and ${report.unmapped.length} unmapped class(es) left for review`);
    } else {
        const left = report.mapped + report.dropped + report.ambiguous.length + report.unmapped.length + report.misuse.length;
        if (left) {
            console.error(`${left} non-semantic colour class(es) left (run --report for the list)`);
            process.exit(1);
        }
        console.log(`no non-semantic colour classes in ${files.length} file(s)`);
    }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main(process.argv.slice(2));
